static bool IsJoinServerVersionSupported(const BYTE* serverVersion)
{
    u_int64 received = 0;
    u_int64 actual = 0;
    for (int i = 0; i < SIZE_PROTOCOLVERSION; ++i)
    {
        received |= serverVersion[i];
        received <<= 8;
        actual |= Version[i];
        actual <<= 8;
    }
    return actual >= received;
}

void ReceiveJoinServer(const BYTE* ReceiveBuffer)
{
    auto Data2 = (LPPRECEIVE_JOIN_SERVER)ReceiveBuffer;

    if (LogIn != 0)
    {
        HeroKey = ((int)(Data2->NumberH) << 8) + Data2->NumberL;
        g_csMapServer.SendChangeMapServer();
    }
    else
    {
        bool accepted = Network::Server::IsSuccessfulResult(
            Network::Server::ResultOperation::JoinServer,
            Data2->Result);
        CUIMng& rUIMng = CUIMng::Instance();

        switch (Data2->Result)
        {
        case 0x01:
            HeroKey = ((int)(Data2->NumberH) << 8) + Data2->NumberL;
            CurrentProtocolState = RECEIVE_JOIN_SERVER_SUCCESS;
            break;

        default:
            g_ErrorReport.Write(L"Connecting error. ");
            g_ErrorReport.WriteCurrentTime();
            rUIMng.PopUpMsgWin(MESSAGE_SERVER_LOST);
            break;
        }

        if (!IsJoinServerVersionSupported(Data2->Version))
        {
            accepted = false;
            rUIMng.HideWin(&rUIMng.m_LoginWin);
            rUIMng.PopUpMsgWin(MESSAGE_VERSION);
            g_ErrorReport.Write(L"Version dismatch - Join server.\r\n");
        }

        auto& automaticLogin = Network::Login::LocalAutoLogin::Instance();
        if (!accepted)
        {
            automaticLogin.Cancel();
        }
        else if (!ReconnectManager::Instance().IsActive())
        {
            if (automaticLogin.TryBeginLogin() && rUIMng.m_LoginWin.RequestAutomaticLogin())
            {
                g_ErrorReport.Write(L"> Local automatic login requested.\r\n");
            }
            else
            {
                rUIMng.ShowWin(&rUIMng.m_LoginWin);
            }
        }

        PublishHaptic(accepted
            ? Core::Haptics::HapticEvent::Confirmed
            : Core::Haptics::HapticEvent::OperationFailed);
    }

    g_GuildCache.Reset();

//#if defined _DEBUG || defined FOR_WORK
//    if (Data2->Result == 0x01)
