    {
        assert(false);
        return;
    }

    int Key = Data->Key;

    CHARACTER* c = &CharactersClient[FindCharacterIndex(Key)];
    OBJECT* o = &c->Object;

    int Type = ((Data->ItemGroup & 0xF) * MAX_ITEM_INDEX) | Data->ItemNumber;
    //BYTE Level = Data->Item[1] & 0xf;
    //BYTE Option = Data->Item[3] & 63;
    //BYTE ExtOption = Data->Item[4];

