    c->PositionY = Data->PositionY;
    c->TargetX = Data->TargetX;
    c->TargetY = Data->TargetY;
    switch (Data->Flags & 0x07)
    {
    case 1:
        CreateTeleportEnd(o);
        // AddDebugText(ReceiveBuffer, Size);
        break;
    case 2:
        if (!gCharacterManager.IsFemale(c->Class))
            SetAction(o, PLAYER_SIT1);
