    {
        CharacterMachine->Equipment[Data->Value].Durability = Data->KeyH;
    }
    else
    {
        ITEM* pItem = g_pMyInventory->FindItem(Data->Value);
        if (pItem == nullptr && IsInventoryExtensionSlot(Data->Value))
        {
            pItem = g_pMyInventoryExt->FindItem(Data->Value);
