void InsertBuffPhysicalEffect(eBuffState buff, OBJECT* o)
{
    switch (buff)
    {
    case eBuff_CursedTempleProdection:
    {
        if (o->Type == MODEL_PLAYER)
        {
            DeleteEffect(MODEL_CURSEDTEMPLE_PRODECTION_SKILL, o);
